package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Merging a person into another on the sheet (a steward only). The merged person's claims move to
 * the other, keeping their numbers and dates, listed after the other's in the order they were added,
 * each unbound from any statement; their name and aliases become aliases of the other; their patrons
 * are added to the other's (not the other themselves, no repeats), anyone naming them as patron names
 * the other instead (no repeats), and their pool memberships move to the other (shares added when the
 * other is already a member). Their statements, holds, watchers and contact are dropped, and they
 * leave the sheet.
 */
@Service
public class PersonMergeService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final WatchRepository watches;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final PoolMemberRepository poolMembers;
    private final SheetService sheets;
    private final RoleService roles;
    private final RollupService rollup;
    private final Audit audit;

    public PersonMergeService(PersonRepository people, PatronRepository patrons, WatchRepository watches,
            ClaimRepository claims, StatementRepository statements, PoolMemberRepository poolMembers,
            SheetService sheets, RoleService roles, RollupService rollup, Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.sheets = sheets;
        this.roles = roles;
        this.rollup = rollup;
        this.audit = audit;
    }

    /**
     * Merge the person into another. Refused (403) to anyone but a steward, (409) for a merge into the
     * person themselves or when either of them is retired.
     */
    @Transactional
    public Person merge(String sheetId, String user, long id, long intoId) {
        roles.refuseViewer(sheetId, user);
        roles.refuseUnlessSteward(sheetId, user);
        sheets.lock(sheetId);
        Person from = person(sheetId, id);
        Person into = person(sheetId, intoId);
        if (from.getId().equals(into.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves.");
        }
        if (from.isRetired() || into.isRetired()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String fromName = from.getName();
        List<String> names = new ArrayList<>(List.of(fromName));
        names.addAll(from.getAliases());

        // the claims, oldest listed first, each listed first in turn: after the other's, in their order
        List<Claim> moved = claims.findBySheetIdAndPersonIdOrderByListedAsc(sheetId, from.getId());
        for (Claim claim : moved) {
            claim.setPersonId(into.getId());
            claim.bind(false, null);
        }
        claims.saveAllAndFlush(moved);
        for (Claim claim : moved) {
            claims.listFirst(claim.getId());
        }

        // patrons: the merged person's go to the other, and whoever named them names the other
        List<Patron> links = patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(l -> l.getPersonId().equals(from.getId()) || l.getPatronId().equals(from.getId())).toList();
        patrons.deleteAll(links);
        patrons.flush();
        for (Patron link : links) {
            long personId = link.getPersonId().equals(from.getId()) ? into.getId() : link.getPersonId();
            long patronId = link.getPatronId().equals(from.getId()) ? into.getId() : link.getPatronId();
            if (personId != patronId && !patrons.existsByPersonIdAndPatronId(personId, patronId)) {
                patrons.saveAndFlush(new Patron(sheetId, personId, patronId));
            }
        }

        // pool memberships move, adding the share where the other is already a member
        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
            var existing = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
            if (existing.isPresent()) {
                existing.get().addShare(member.getShare());
                poolMembers.save(existing.get());
                poolMembers.delete(member);
            } else {
                member.setPersonId(into.getId());
                poolMembers.save(member);
            }
        }
        poolMembers.flush();

        List<Statement> theirStatements = statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(s -> Objects.equals(s.getPersonId(), from.getId())).toList();
        statements.deleteAll(theirStatements);
        statements.flush();
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
        watches.flush();

        // listing the claims first cleared what was read: read both people again
        people.delete(person(sheetId, from.getId()));
        people.flush();
        Person merged = person(sheetId, into.getId());
        names.forEach(merged::addAlias);
        Person saved = people.saveAndFlush(merged);

        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user + " from=" + fromName + " into="
                + saved.getName());
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    private Person person(String sheetId, long id) {
        return people.lockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Locale;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Listing, adding and editing the people on a sheet. */
@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record ListPeopleRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    public record AddPersonRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotBlank @Size(max = 200) String name, @NotNull @Pattern(regexp = "[ABC]") String grade, @Min(0) Integer terms,
            @Size(max = 200) String contact) {
    }

    public record UpdatePersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate gradeFrom, @NotNull Long version,
            @Min(0) Integer terms, @Size(max = 200) String contact) {
    }

    public record AddAliasRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotBlank @Size(max = 200) String alias) {
    }

    public record MergePersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotNull Long intoId) {
    }

    public record BulkGradeRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotEmpty List<@NotNull Long> ids,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate from) {
    }

    /** How many people were given the grade, and each as the store now holds them. */
    public record BulkGradeResponse(int graded, List<PersonResponse> people) {
    }

    public record RetirePersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, LocalDate date) {
    }

    public record HoldPersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, LocalDate from, LocalDate to) {
    }

    public record AddPatronRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotNull Long patronId) {
    }

    public record ListWatchedRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user) {
    }

    public record WatchPersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotNull Boolean watch) {
    }

    public record PatronResponse(long personId, long patronId) {
    }

    /** One of a person's grades, from a from-date (null: from the beginning of time). */
    public record GradeResponse(LocalDate from, String grade) {
    }

    /** One of a person's holds, from a from-date to a to-date (null: open-ended). */
    public record HoldResponse(LocalDate from, LocalDate to) {
    }

    /** A person, with every grade recorded for them, the one from the beginning of time first, their own terms or null, their contact or null, and their aliases sorted as names are compared. */
    public record PersonResponse(long id, String name, List<GradeResponse> grades, long version, boolean retired,
            LocalDate retiredFrom, boolean held, List<HoldResponse> holds, Integer terms, String contact,
            List<String> aliases) {
    }

    public static PersonResponse response(Person person) {
        List<GradeResponse> grades = person.getGrades().stream()
                .map(g -> new GradeResponse(g.getFromDate(), g.getGrade())).toList();
        return new PersonResponse(person.getId(), person.getName(), grades, person.getVersion(),
                person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                person.getHolds().stream().map(h -> new HoldResponse(h.getFromDate(), h.getToDate())).toList(),
                person.getTerms(), person.getContact(), person.getAliases());
    }

    /** A contact as stored: trimmed and lower-cased; null when blank. */
    private static String contact(String contact) {
        String c = contact == null ? "" : contact.trim().toLowerCase(Locale.ROOT);
        return c.isEmpty() ? null : c;
    }

    private final PersonService service;
    private final PersonMergeService merges;

    public PersonController(PersonService service, PersonMergeService merges) {
        this.service = service;
        this.merges = merges;
    }

    @PostMapping("/list")
    public List<PersonResponse> list(@Valid @RequestBody ListPeopleRequest req) {
        return service.list(req.sheet().trim()).stream().map(PersonController::response).toList();
    }

    @PostMapping("/add")
    public PersonResponse add(@Valid @RequestBody AddPersonRequest req) {
        return response(service.add(req.sheet().trim(), req.user().trim(), req.name().trim(), req.grade(),
                req.terms(), contact(req.contact())));
    }

    @PostMapping("/update")
    public PersonResponse update(@Valid @RequestBody UpdatePersonRequest req) {
        return response(service.update(req.sheet().trim(), req.user().trim(), req.id(), req.version(), req.name().trim(),
                req.grade(), req.gradeFrom(), req.terms(), contact(req.contact())));
    }

    @PostMapping("/aliases/add")
    public PersonResponse addAlias(@Valid @RequestBody AddAliasRequest req) {
        return response(service.addAlias(req.sheet().trim(), req.user().trim(), req.id(), req.alias().trim()));
    }

    /** Merge the person into another; answers the other as the store now holds them. */
    @PostMapping("/merge")
    public PersonResponse merge(@Valid @RequestBody MergePersonRequest req) {
        return response(merges.merge(req.sheet().trim(), req.user().trim(), req.id(), req.intoId()));
    }

    @PostMapping("/bulk-grade")
    public BulkGradeResponse bulkGrade(@Valid @RequestBody BulkGradeRequest req) {
        List<PersonResponse> graded = service.bulkGrade(req.sheet().trim(), req.user().trim(), req.ids(), req.grade(),
                req.from()).stream().map(PersonController::response).toList();
        return new BulkGradeResponse(graded.size(), graded);
    }

    @PostMapping("/retire")
    public PersonResponse retire(@Valid @RequestBody RetirePersonRequest req) {
        return response(service.retire(req.sheet().trim(), req.user().trim(), req.id(), req.date()));
    }

    @PostMapping("/hold")
    public PersonResponse hold(@Valid @RequestBody HoldPersonRequest req) {
        return response(service.hold(req.sheet().trim(), req.user().trim(), req.id(), req.from(), req.to()));
    }

    @PostMapping("/patrons/list")
    public List<PatronResponse> patrons(@Valid @RequestBody ListPeopleRequest req) {
        return service.patrons(req.sheet().trim()).stream()
                .map(p -> new PatronResponse(p.getPersonId(), p.getPatronId())).toList();
    }

    @PostMapping("/patrons/add")
    public PatronResponse addPatron(@Valid @RequestBody AddPatronRequest req) {
        Patron added = service.addPatron(req.sheet().trim(), req.user().trim(), req.id(), req.patronId());
        return new PatronResponse(added.getPersonId(), added.getPatronId());
    }

    /** The ids of the people the user watches on the sheet. */
    @PostMapping("/watched")
    public List<Long> watched(@Valid @RequestBody ListWatchedRequest req) {
        return service.watched(req.sheet().trim(), req.user().trim());
    }

    @PostMapping("/watch")
    public void watch(@Valid @RequestBody WatchPersonRequest req) {
        service.watch(req.sheet().trim(), req.user().trim(), req.id(), req.watch());
    }
}

