package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and their grades (A, B or C), each from a from-date, and the date they are retired from, if any;
 * and the holds they have had, each over a span of dates. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded, the first from the beginning of time (no from-date), the others each from a date. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedGrade> grades = new ArrayList<>();

    /** The person's own terms in days, or null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, trimmed and lower-cased, or null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** Set once retired: the person counts as retired at once, whatever the date. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The sheet's today when the person was retired; none while not retired. */
    @Column(name = "retired_on")
    private LocalDate retiredOn;

    /** The sheet's today when the person was added; none for one added before it was recorded. */
    @Column(name = "added_on")
    private LocalDate addedOn;

    /** The person's OPEN claims dated within a hold, and not bound by a statement, count in no live total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedHold> holds = new ArrayList<>();

    /** The person's aliases, trimmed; each shares the names' uniqueness on the sheet. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias", nullable = false)
    private Set<String> aliases = new HashSet<>();

    /** Bumped on every save; an edit must carry the version it was made from. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade, LocalDate addedOn) {
        this.sheetId = sheetId;
        this.name = name;
        this.addedOn = addedOn;
        this.grades.add(new DatedGrade(null, grade, addedOn));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, the one from the beginning of time first and then by from-date. */
    public List<DatedGrade> getGrades() {
        return grades.stream().sorted(Comparator.comparing(DatedGrade::getFromDate,
                Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        String found = null;
        for (DatedGrade g : getGrades()) {
            if (g.getFromDate() == null || !g.getFromDate().isAfter(date)) {
                found = g.getGrade();
            }
        }
        return found;
    }

    /**
     * The grade in force on a date as the person stood at the end of a day: the one with the latest
     * from-date on or before the date, of those recorded while the sheet's today was on or before the day.
     */
    public String gradeOn(LocalDate date, LocalDate asOf) {
        String found = null;
        for (DatedGrade g : getGrades()) {
            if (g.madeBy(asOf) && (g.getFromDate() == null || !g.getFromDate().isAfter(date))) {
                found = g.getGrade();
            }
        }
        return found;
    }

    /**
     * Record the grade from a date, replacing any grade already recorded from that same date;
     * {@code madeOn} is the sheet's today.
     */
    public void setGradeFrom(LocalDate fromDate, String grade, LocalDate madeOn) {
        grades.removeIf(g -> fromDate.equals(g.getFromDate()));
        grades.add(new DatedGrade(fromDate, grade, madeOn));
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    /** Retire the person from a date; {@code madeOn} is the sheet's today. */
    public void setRetiredFrom(LocalDate retiredFrom, LocalDate madeOn) {
        this.retiredFrom = retiredFrom;
        this.retiredOn = madeOn;
    }

    /** Whether the person had been added by the end of a day: the sheet's today then on or before it. */
    public boolean addedBy(LocalDate day) {
        return addedOn == null || !addedOn.isAfter(day);
    }

    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the retirement date is reached on a day (the day on or after it). */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    /** The holds recorded, by from-date. */
    /** The person's aliases, sorted as names are compared: without regard to case. */
    public List<String> getAliases() {
        return aliases.stream().sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT))
                .thenComparing(Comparator.naturalOrder())).toList();
    }

    public void addAlias(String alias) {
        aliases.add(alias);
    }

    public List<DatedHold> getHolds() {
        return holds.stream().sorted(Comparator.comparing(DatedHold::getFromDate)
                .thenComparing(DatedHold::getToDate, Comparator.nullsLast(Comparator.naturalOrder()))).toList();
    }

    /** Add a hold; {@code madeOn} is the sheet's today. */
    public void addHold(LocalDate fromDate, LocalDate toDate, LocalDate madeOn) {
        holds.add(new DatedHold(fromDate, toDate, madeOn));
    }

    /** Whether the person has any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether a day lies within one of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /**
     * Whether a claim of this person counts toward the live totals: an open claim dated within a
     * hold does not, nor does one of a person whose retirement date the sheet's today has reached,
     * unless a statement binds it; nor does a claim deferred on the sheet's today.
     */
    public boolean counts(Claim claim, LocalDate today) {
        return counts(claim, claim.getStatus(), today);
    }

    /**
     * Whether a claim of this person counts by the same rules, had it the given status; a hold or a
     * reached retirement takes out only a claim that is open now as well (one since settled or voided is not).
     */
    public boolean counts(Claim claim, ClaimStatus status, LocalDate today) {
        return status.counts() && !claim.isDeferredOn(status, today) && (claim.isStated()
                || !(status.isOpen() && claim.getStatus().isOpen() && (heldOn(claim.getDate()) || retiredOn(today))));
    }

    /**
     * Whether a claim of this person counted at the end of a day, as the person stood then: had it
     * the given status then, and was it bound by a statement then ({@code stated}). The day stands in
     * for the sheet's today, and only holds and a retirement recorded while the sheet's today was on
     * or before it count.
     */
    public boolean countedAsOf(Claim claim, ClaimStatus status, LocalDate day, boolean stated) {
        boolean held = holds.stream().anyMatch(h -> h.madeBy(day) && h.covers(claim.getDate()));
        boolean retired = retiredFrom != null && (retiredOn == null || !retiredOn.isAfter(day))
                && !day.isBefore(retiredFrom);
        return status.counts() && !claim.isDeferredAsOf(status, day)
                && (stated || !(status.isOpen() && (held || retired)));
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** One of a person's grades: in force from its from-date (none: from the beginning of time) until their next. */
@Embeddable
public class DatedGrade {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "grade", nullable = false)
    private String grade;

    /** The sheet's today when it was recorded; none: from the beginning of time. */
    @Column(name = "made_on")
    private LocalDate madeOn;

    protected DatedGrade() {
    }

    public DatedGrade(LocalDate fromDate, String grade, LocalDate madeOn) {
        this.fromDate = fromDate;
        this.grade = grade;
        this.madeOn = madeOn;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getGrade() {
        return grade;
    }

    /** Whether it was recorded by the end of a day: the sheet's today then on or before it. */
    public boolean madeBy(LocalDate day) {
        return madeOn == null || !madeOn.isAfter(day);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The people on a sheet: listed in the order they were added, added and edited by name and grade. A
 * person's grade is dated: the first applies from the beginning of time, and each edit records the
 * grade from its from-date (the sheet's today when none is given), keeping those already recorded;
 * an edit leaving the grade in force on the sheet's today as it is, with no from-date, records none.
 * A
 * name is unique on the sheet, compared without regard to case (names arrive trimmed). A person can
 * be retired from a date (the sheet's today when none is given); they count as retired at once. A
 * person can be put on hold over a span of dates, and may have several holds over time. A person can name other people on the sheet as
 * their patrons, one at a time: not themselves, and not the same person twice. A user can watch a
 * person, and stop watching them; each user's watching is their own. A person may have their own
 * terms, in days; a claim's due-by takes them before the terms of the person's grade and the sheet's.
 * A person may have a contact (arriving trimmed and lower-cased, null for none), unique on the sheet.
 * A person may have aliases (arriving trimmed), sharing the names' uniqueness: an alias equals no name
 * or alias on the sheet, and no name equals an alias.
 */
@Service
public class PersonService {

    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final PatronRepository patrons;
    private final RoleService roles;
    private final WatchRepository watches;

    public PersonService(PersonRepository people, SheetService sheets, Audit audit, RollupService rollup,
            PatronRepository patrons, RoleService roles, WatchRepository watches) {
        this.roles = roles;
        this.watches = watches;
        this.people = people;
        this.patrons = patrons;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
        return add(sheetId, user, name, grade, terms, null);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        roles.refuseViewer(sheetId, user);
        sheets.load(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, name) || people.existsAliasOnSheet(sheetId, name)) {
            throw nameInUse();
        }
        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
            throw contactInUse();
        }
        Person person = new Person(sheetId, name, grade, sheets.today(sheetId));
        person.setTerms(terms);
        person.setContact(contact);
        Person added = save(person);
        audit.recordOnCommit(record("PERSON_ADDED", sheetId, user, added, sheets.today(sheetId))
                + (terms != null ? " terms=" + terms : "") + (contact != null ? " contact=" + contact : ""));
        rollup.recordChanges(sheetId, user, before);
        return added;
    }

    @Transactional
    public Person update(String sheetId, String user, long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        roles.refuseViewer(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (person.getVersion() != version) {
            throw stale();
        }
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, name, id) || people.existsAliasOnSheet(sheetId, name)) {
            throw nameInUse();
        }
        if (contact != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contact, id)) {
            throw contactInUse();
        }
        LocalDate today = sheets.today(sheetId);
        Integer termsBefore = person.getTerms();
        String contactBefore = person.getContact();
        person.setName(name);
        person.setTerms(terms);
        person.setContact(contact);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade, today);
        }
        Person saved = save(person);
        audit.recordOnCommit(record("PERSON_EDITED", sheetId, user, saved, today)
                + (Objects.equals(termsBefore, terms) ? "" : " terms=" + (terms != null ? terms : ""))
                + (Objects.equals(contactBefore, contact) ? "" : " contact=" + (contact != null ? contact : "")));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** Give the person an alias; refused (409) when it equals any name or alias on the sheet. */
    @Transactional
    public Person addAlias(String sheetId, String user, long id, String alias) {
        roles.refuseViewer(sheetId, user);
        Person person = people.lockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, alias) || people.existsAliasOnSheet(sheetId, alias)) {
            throw nameInUse();
        }
        person.addAlias(alias);
        Person saved = save(person);
        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " alias=" + alias);
        return saved;
    }

    /**
     * Give each of the people a grade from a from-date (the sheet's today when none is given), in list
     * order, exactly as editing each with the person form would (name, terms and contact kept). All or none: a
     * person not on the sheet refuses the lot. A viewer may grade no one: each person is refused and
     * none is graded.
     */
    @Transactional
    public List<Person> bulkGrade(String sheetId, String user, List<Long> ids, String grade, LocalDate gradeFrom) {
        try {
            roles.refuseViewer(sheetId, user);
        } catch (ResponseStatusException e) {
            if (e.getStatusCode() == HttpStatus.FORBIDDEN) {
                return List.of();
            }
            throw e;
        }
        Set<Long> wanted = new HashSet<>(ids);
        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(p -> wanted.contains(p.getId())).toList();
        if (chosen.size() != wanted.size()) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet.");
        }
        return chosen.stream().map(p -> update(sheetId, user, p.getId(), p.getVersion(), p.getName(), grade,
                gradeFrom, p.getTerms(), p.getContact())).toList();
    }

    /**
     * Retire the person from a date, or from the sheet's today when none is given. Once the sheet's
     * today reaches that date their OPEN claims leave every live total, so the figures that move are recorded.
     */
    @Transactional
    public Person retire(String sheetId, String user, long id, LocalDate date) {
        roles.refuseViewer(sheetId, user);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate from = date != null ? date : sheets.today(sheetId);
        person.setRetiredFrom(from, sheets.today(sheetId));
        Person saved = save(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName() + " from="
                + from);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Put the person on hold from a date (the sheet's today when none is given) to an optional
     * to-date; refused (400) when the to-date is before the from-date. Their OPEN claims dated within
     * the hold leave every live total, so the figures that move are recorded.
     */
    @Transactional
    public Person hold(String sheetId, String user, long id, LocalDate fromDate, LocalDate toDate) {
        roles.refuseViewer(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.lockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        LocalDate from = fromDate != null ? fromDate : sheets.today(sheetId);
        if (toDate != null && toDate.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
        }
        person.addHold(from, toDate, sheets.today(sheetId));
        Person saved = save(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName() + " from="
                + from);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    @Transactional(readOnly = true)
    public List<Patron> patrons(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /**
     * Name another person on the sheet as the person's patron; refused (409) when it is the person
     * themselves or already one of their patrons.
     */
    @Transactional
    public Patron addPatron(String sheetId, String user, long id, long patronId) {
        roles.refuseViewer(sheetId, user);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet."));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw patronTaken();
        }
        Patron added;
        try {
            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException e) {
            throw patronTaken();
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " patron=" + patron.getName());
        return added;
    }

    /** The ids of the people the user watches on the sheet. */
    @Transactional(readOnly = true)
    public List<Long> watched(String sheetId, String user) {
        return watches.findBySheetIdAndUserName(sheetId, user).stream().map(Watch::getPersonId).toList();
    }

    /**
     * Start ({@code on}) or stop watching the person as the user; already so, nothing changes and
     * nothing is recorded.
     */
    @Transactional
    public void watch(String sheetId, String user, long id, boolean on) {
        roles.refuseViewer(sheetId, user);
        sheets.refuseIfArchived(sheetId);
        Person person = people.lockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        var existing = watches.findByPersonIdAndUserName(person.getId(), user);
        if (on == existing.isPresent()) {
            return;
        }
        if (on) {
            watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
        } else {
            watches.delete(existing.get());
            watches.flush();
        }
        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName());
    }

    private static ResponseStatusException patronTaken() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
    }

    /** A person's record, with the grade in force on the sheet's today. */
    private static String record(String event, String sheetId, String user, Person person, LocalDate today) {
        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade="
                + person.gradeOn(today);
    }

    /**
     * Save, refusing a name another user took on the sheet since it was checked, and an edit another
     * user saved over since the person was read.
     */
    private Person save(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (DataIntegrityViolationException e) {
            throw person.getContact() != null && String.valueOf(e.getMostSpecificCause().getMessage())
                    .toUpperCase().contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
        } catch (ObjectOptimisticLockingFailureException e) {
            throw stale();
        }
    }

    /** The edit was made from a version of the person that another user has since saved over. */
    private static ResponseStatusException stale() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved this person since it was opened.");
    }

    private static ResponseStatusException contactInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on this sheet.");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** A sheet's people in the order they were added. */
    List<Person> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** The person, locked until the transaction ends, so their statements are taken one at a time. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select p from Person p where p.id = :id and p.sheetId = :sheetId")
    Optional<Person> lockByIdAndSheetId(Long id, String sheetId);

    /** Whether another person on the sheet has this name, compared without regard to case. */
    boolean existsBySheetIdAndNameIgnoreCaseAndIdNot(String sheetId, String name, Long id);

    boolean existsBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** Whether a person on the sheet has this contact. */
    boolean existsBySheetIdAndContact(String sheetId, String contact);

    /** Whether another person on the sheet has this contact. */
    boolean existsBySheetIdAndContactAndIdNot(String sheetId, String contact, Long id);

    /** The person on the sheet with this name, compared without regard to case. */
    Optional<Person> findBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** Whether a person on the sheet has this alias, compared without regard to case. */
    @Query("select count(p) > 0 from Person p join p.aliases a where p.sheetId = :sheetId and lower(a) = lower(:alias)")
    boolean existsAliasOnSheet(String sheetId, String alias);

    /** The person on the sheet with this name or alias, compared without regard to case. */
    @Query("select distinct p from Person p left join p.aliases a where p.sheetId = :sheetId"
            + " and (lower(p.name) = lower(:name) or lower(a) = lower(:name))")
    Optional<Person> findBySheetIdAndNameOrAlias(String sheetId, String name);
}

