import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/** Sends the date the screen shows the sheet as of with every API request, when one is set. */
export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
  const asOf = inject(Session).asOf();
  return asOf && req.url.startsWith('/api/') ? next(req.clone({ setHeaders: { 'X-As-Of': asOf } })) : next(req);
};
  contact: string | null;
  /** The person's aliases, sorted as names are compared. */
  aliases: string[];
}

/** One of a person's holds: from its from-date to its to-date (null: open-ended), both inclusive. */
/** The figures of a sheet's descendants added up: each sheet's as that sheet shows it. */
interface Descendants {
  peopleCount: number;
  dueTotal: string;
  overdueTotal: string;
}

const NO_DESCENDANTS: Descendants = { peopleCount: 0, dueTotal: '0.00', overdueTotal: '0.00' };

interface DatedHold {
  from: string;
  to: string | null;
}

/** Whether a day lies within one of the person's holds. */
